using System.IO.Pipes;using System.Security.Principal;using System.Text.Json;using Microsoft.Extensions.Logging.Abstractions;using Microsoft.Extensions.Options;using TuoiTho.Core.Policy;using TuoiTho.Core.Time;using TuoiTho.Parent;using TuoiTho.Service;using TuoiTho.Storage;
namespace TuoiTho.Tests;
public sealed class M1TesterPackageTests
{
 [Fact] public async Task ParentClientReceivesAcceptedResponse(){var name=$"TuoiTho.Parent.Test.{Guid.NewGuid():N}";var ready=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var server=Task.Run(async()=>{using var pipe=new NamedPipeServerStream(name,PipeDirection.InOut,1,PipeTransmissionMode.Byte,PipeOptions.Asynchronous);ready.SetResult();await pipe.WaitForConnectionAsync();using var reader=new StreamReader(pipe,leaveOpen:true);var command=JsonSerializer.Deserialize<ParentControlCommand>((await reader.ReadLineAsync())!);Assert.Equal(ParentControlAction.GetStatus,command!.Action);using var writer=new StreamWriter(pipe,leaveOpen:true){AutoFlush=true};await writer.WriteLineAsync(JsonSerializer.Serialize(new ParentControlResult(true,null,null,new ParentControlStatus("p",7,true,1,3,0,2,"ALLOWED"))));});await ready.Task;var result=await new LocalParentControlClient(name).SendAsync(new(ParentControlAction.GetStatus,"p",7));await server;Assert.True(result.Accepted);Assert.Equal("ALLOWED",result.Status!.State);}
 [Fact] public async Task ServerReadsBeforeImpersonatingAndReturnsResponse(){var sid=WindowsIdentity.GetCurrent().User!;var name=$"TuoiTho.Parent.Order.{Guid.NewGuid():N}";var ready=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var server=Task.Run(async()=>{using var pipe=ParentControlPipeSecurity.CreateServer(name,[sid.Value]);ready.SetResult();await pipe.WaitForConnectionAsync();using var reader=new StreamReader(pipe,leaveOpen:true);var command=await ParentControlListener.ReadCommandAsync(reader,CancellationToken.None);Assert.NotNull(command);Assert.Equal(sid.Value,ParentControlListener.GetAuthenticatedSid(pipe));using var writer=new StreamWriter(pipe,leaveOpen:true){AutoFlush=true};await writer.WriteLineAsync(JsonSerializer.Serialize(new ParentControlResult(true,null)));});await ready.Task;var result=await new LocalParentControlClient(name).SendAsync(new(ParentControlAction.GetStatus,"child",7));await server;Assert.True(result.Accepted);} [Fact] public async Task StatusAndUnauthorizedAreReported(){var clock=new FakeClock(new DateTimeOffset(2026,9,14,9,0,0,TimeSpan.Zero),TimeZoneInfo.Utc);var policy=Policy();var store=new Store(policy);var service=new ParentControlService(store,new FakeTimeUsageStore(),clock,new DeviceTimePolicyEngine(clock),new PolicyChangeSignal());var rejected=await service.ExecuteAsync(new(ParentControlAction.GetStatus,"child",7),"child",new HashSet<string>{"parent"});Assert.False(rejected.Accepted);var accepted=await service.ExecuteAsync(new(ParentControlAction.GetStatus,"child",7),"parent",new HashSet<string>{"parent"});Assert.True(accepted.Accepted);Assert.True(accepted.Status!.TestMode);Assert.Equal("ALLOWED",accepted.Status.State);}
 [Fact] public async Task DesktopControllerSurfacesStatusAndAcceptedGrant(){var client=new FakeClient(new ParentControlResult(true,null,null,new ParentControlStatus("child",7,true,1,3,15,17,"ALLOWED")));var ui=new ParentDesktopController(client,"child",7);var status=await ui.RefreshAsync();Assert.True(status.Success);Assert.Equal("ALLOWED",status.Status!.State);var grant=await ui.SendAsync(ParentControlAction.GrantMinutes,15);Assert.True(grant.Success);Assert.Equal(ParentControlAction.GrantMinutes,client.Last!.Action);Assert.Equal(15,client.Last.Minutes);Assert.Equal("child",client.Last.ProfileId);Assert.Equal(7,client.Last.ManagedSessionId);}
 [Fact] public async Task DesktopControllerSurfacesRejectedResponse(){var ui=new ParentDesktopController(new FakeClient(new ParentControlResult(false,"UNAUTHORIZED")),"child",7);var result=await ui.SendAsync(ParentControlAction.SetParentLock);Assert.False(result.Success);Assert.Contains("TỪ CHỐI",result.Message);Assert.Contains("quyền",result.Message);} [Fact] public async Task BootstrapForcesTestModeAndCurrentSession(){var path=Path.Combine(Path.GetTempPath(),$"m1-{Guid.NewGuid():N}.db");try{var db=new SqliteDatabase(path);var store=new SqliteDeviceTimePolicyStore(db);var options=Options.Create(new M1BootstrapOptions{Enabled=true,ProfileId="m1",ManagedSessionId=7,ManagedUserSid="S-1-5-21-test",QuotaMinutes=3});var boot=new M1Bootstrapper(db,store,options,new PolicyChangeSignal());await boot.StartAsync(CancellationToken.None);var policy=(await store.LoadAsync("m1"))!;Assert.True(policy.TestMode);Assert.Equal(7,policy.ManagedSessionId);Assert.Equal("S-1-5-21-test",policy.ManagedUserSid);Assert.Equal(3,policy.DailyQuotaMinutes);}finally{if(File.Exists(path))File.Delete(path);}}
 [Fact] public void StartScriptForcesTestModeAndLaunchesDesktopParent(){var text=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"..","..","..","..","..","scripts","M1-START.ps1"));Assert.Contains("M1TestMode='true'",text);Assert.Contains("TimeTracking__IdleThresholdMinutes='1'",text);Assert.Contains("TimeTracking__IdlePollIntervalSeconds='5'",text);Assert.Contains("RawInputIdleSeconds,WindowsIdleSeconds,ActivityState,RecordedTodaySeconds",text);Assert.Contains("src/TuoiTho.Parent",text);Assert.Contains("$parentExe",text);Assert.DoesNotContain("localhost",text,StringComparison.OrdinalIgnoreCase);} [Fact] public void ProductionIdleDefaultsRemainFiveMinutes(){var options=new WindowsTimeTrackingOptions();Assert.Equal(5,options.IdleThresholdMinutes);Assert.Equal(15,options.IdlePollIntervalSeconds);} [Fact] public void StopScriptCannotEnforce(){var text=File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"..","..","..","..","..","scripts","M1-STOP.ps1"));Assert.DoesNotContain("WTSDisconnect",text);Assert.DoesNotContain("shutdown",text,StringComparison.OrdinalIgnoreCase);Assert.Contains("TestMode",text);}
 [Fact] public async Task ResetM1ClearsStaleLockedUsageGrantsAndPolicyState(){var clock=new FakeClock(new DateTimeOffset(2026,9,14,9,0,0,TimeSpan.Zero),TimeZoneInfo.Utc);var policy=new DeviceTimePolicy("m1-child",7,30,[new AllowedUsageWindow(DayOfWeek.Monday,new(0,0),new(23,59))],DeviceTimePolicy.DefaultWarnings,true,true,true){ManagedUserSid="S-1-5-21-child"};var store=new M1ResetStore(policy,[new TemporaryGrant(30,clock.UtcNow.AddHours(1))]);var usage=new FakeTimeUsageStore();var date=new DateOnly(2026,9,14);await usage.SaveAsync("m1-child",new TimeTrackingCheckpoint(7,SessionActivityState.Locked,clock.UtcNow,clock.UtcNow),[new DailyUsageSlice(date,TimeSpan.FromMinutes(2))]);var service=new ParentControlService(store,usage,clock,new DeviceTimePolicyEngine(clock),new PolicyChangeSignal());var result=await service.ExecuteAsync(new(ParentControlAction.ResetM1,"m1-child",7),"parent",new HashSet<string>{"parent"});Assert.True(result.Accepted);Assert.Equal(0,result.Status!.UsedMinutes);Assert.Equal(3,result.Status.QuotaMinutes);Assert.Equal(0,result.Status.GrantMinutes);Assert.Equal("ALLOWED",result.Status.State);Assert.True(result.Policy!.TestMode);Assert.False(result.Policy.ParentOverride);Assert.False(result.Policy.ParentLock);var baseline=await usage.LoadCheckpointAsync("m1-child");Assert.NotNull(baseline);Assert.Equal(clock.UtcNow,baseline!.LastObservedAtUtc);Assert.Empty(await store.GetGrantsAsync("m1-child"));} private sealed class FakeClient(ParentControlResult result):IParentControlClient{public ParentControlCommand? Last{get;private set;}public Task<ParentControlResult> SendAsync(ParentControlCommand command,CancellationToken token=default){Last=command;return Task.FromResult(result);}} private static DeviceTimePolicy Policy()=>new("child",7,3,[new AllowedUsageWindow(DayOfWeek.Monday,new(0,0),new(23,59))],DeviceTimePolicy.DefaultWarnings,false,false,true){ManagedUserSid="S-1-5-21-child"};
 private sealed class M1ResetStore(DeviceTimePolicy policy,IReadOnlyList<TemporaryGrant> initial):IDeviceTimePolicyStore{private DeviceTimePolicy current=policy;private List<TemporaryGrant> grants=[..initial];public Task<DeviceTimePolicy?> LoadAsync(string id,CancellationToken c=default)=>Task.FromResult<DeviceTimePolicy?>(current);public Task SaveAsync(DeviceTimePolicy p,CancellationToken c=default){current=p;return Task.CompletedTask;}public Task AddGrantAsync(string id,TemporaryGrant g,CancellationToken c=default){grants.Add(g);return Task.CompletedTask;}public Task<IReadOnlyList<TemporaryGrant>> GetGrantsAsync(string id,CancellationToken c=default)=>Task.FromResult<IReadOnlyList<TemporaryGrant>>(grants);public Task ClearGrantsAsync(string id,CancellationToken c=default){grants.Clear();return Task.CompletedTask;}} private sealed class Store(DeviceTimePolicy p):IDeviceTimePolicyStore{public Task<DeviceTimePolicy?> LoadAsync(string id,CancellationToken c=default)=>Task.FromResult<DeviceTimePolicy?>(p);public Task SaveAsync(DeviceTimePolicy p,CancellationToken c=default)=>Task.CompletedTask;public Task AddGrantAsync(string id,TemporaryGrant g,CancellationToken c=default)=>Task.CompletedTask;public Task<IReadOnlyList<TemporaryGrant>> GetGrantsAsync(string id,CancellationToken c=default)=>Task.FromResult<IReadOnlyList<TemporaryGrant>>([]);}
}